from openai import OpenAI

client = OpenAI()

EXAMPLES = [
    ("happy", "positive"),
    ("sad", "negative"),
    ("angry", "negative"),
]

def classify(word: str) -> str:
    shots = "\n".join(f"Word: {w} -> {l}" for w, l in EXAMPLES)
    r = client.chat.completions.create(
        model="{{model_name}}",
        messages=[{"role": "user", "content": f"{shots}\nWord: {word} ->"}],
    )
    return r.choices[0].message.content.strip()

if __name__ == "__main__":
    print(classify("joyful"))
